        display: grid;
        grid-template-columns: minmax(0, 1fr) minmax(18rem, 30rem);
        gap: clamp(1.5rem, 4vw, 4rem);
        align-items: center;
      }

      .hero {
        min-width: 0;
      }

      .eyebrow {
        display: inline-flex;
        margin: 0 0 1rem;
        border: 1px solid #b4c6fc;
        border-radius: 999px;
        background: var(--surface-muted);
        color: #1849a9;
        padding: 0.35rem 0.8rem;
        font-size: 0.875rem;
        font-weight: 700;
