  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div class="page-shell">
      <header>
        <a class="brand" href="#" aria-label="Acme Support home">
          <span class="brand-mark" aria-hidden="true">A</span>
          <span>Acme Support</span>
        </a>
      </header>
      <main id="main-content">
        <div id="app"></div>
      </main>
    </div>

    <script>
      const fieldConfig = [
        {
          id: "fullName",
          name: "fullName",
          label: "Full name",
          autocomplete: "name",
          type: "text",
          required: true,
          placeholder: "Alex Morgan"
        },
        {
          id: "email",
          name: "email",
          label: "Email address",
          autocomplete: "email",
          type: "email",
          required: true,
          placeholder: "alex@example.com"
        },
        {
          id: "phone",
          name: "phone",
          label: "Phone number",
          autocomplete: "tel",
          type: "tel",
          required: false,
          placeholder: "+1 555-123-4567",
          helperText: "Use digits, spaces, dashes, or parentheses. Example: +1 555-123-4567."
        }
      ];

      const errorMessages = {
        fullName: {
          required: "Enter your full name."
        },
        email: {
          required: "Enter your email address.",
          format: "Enter a valid email address, such as alex@example.com."
        },
        phone: {
          format: "Enter a valid phone number using 7 to 15 digits."
        }
      };

      const formState = {
        values: {
          fullName: "",
          email: "",
          phone: ""
        },
        errors: {}
      };

      function escapeHtml(value) {
        return String(value).replace(/[&<>"']/g, (character) => {
          const entities = {
            "&": "&amp;",
            "<": "&lt;",
            ">": "&gt;",
            '"': "&quot;",
            "'": "&#039;"
          };
          return entities[character];
        });
      }

      function FormField({ field }) {
        const helperId = `${field.id}-helper`;
        const errorId = `${field.id}-error`;
        const describedBy = [field.helperText ? helperId : null, errorId]
          .filter(Boolean)
          .join(" ");

        return `
          <div class="form-field">
            <label for="${field.id}">
              ${field.label}
              ${
                field.required
                  ? '<span class="required-indicator" aria-hidden="true">*</span>'
                  : '<span class="optional-indicator">(optional)</span>'
              }
            </label>
            <input
              id="${field.id}"
              name="${field.name}"
              type="${field.type}"
              autocomplete="${field.autocomplete}"
              placeholder="${field.placeholder}"
              ${field.required ? "required" : ""}
              aria-describedby="${describedBy}"
              aria-invalid="false"
            >
            ${
              field.helperText
                ? `<p class="helper-text" id="${helperId}">${field.helperText}</p>`
                : ""
            }
            <p class="error-message" id="${errorId}"></p>
          </div>
        `;
      }

      function ContactForm() {
        return `
          <section class="hero" aria-labelledby="support-heading">
            <p class="eyebrow">Support request</p>
            <h1 id="support-heading">How can we help?</h1>
            <p>
              Send our support team your contact details and we will route your
              request to the right specialist.
            </p>
          </section>
          <section class="support-card" aria-labelledby="form-heading">
            <h2 class="card-heading" id="form-heading">Contact support</h2>
            <p class="card-copy">Fields marked with an asterisk are required.</p>
            <form id="support-form" novalidate>
              ${fieldConfig.map((field) => FormField({ field })).join("")}
              <div class="button-row">
                <button type="submit">Submit support request</button>
              </div>
              <p class="form-status" id="form-status" aria-live="polite"></p>
            </form>
          </section>
        `;
      }

      function validateField(name, value) {
        const trimmedValue = value.trim();

        if (name === "fullName" && trimmedValue.length === 0) {
          return errorMessages.fullName.required;
        }

        if (name === "email") {
          if (trimmedValue.length === 0) {
            return errorMessages.email.required;
          }

          if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmedValue)) {
            return errorMessages.email.format;
          }
        }

        if (name === "phone" && trimmedValue.length > 0) {
          const digitCount = trimmedValue.replace(/\D/g, "").length;
          const allowedCharacters = /^[+()\-\s.\d]+$/.test(trimmedValue);

          if (!allowedCharacters || digitCount < 7 || digitCount > 15) {
            return errorMessages.phone.format;
          }
        }

        return "";
      }

      function setFieldError(input, message) {
        const errorElement = document.getElementById(`${input.id}-error`);
        const hasError = Boolean(message);

        input.setAttribute("aria-invalid", String(hasError));
        errorElement.textContent = message;
        errorElement.classList.toggle("is-visible", hasError);
      }

      function updateField(input) {
        formState.values[input.name] = input.value;
        const message = validateField(input.name, input.value);
        formState.errors[input.name] = message;
        setFieldError(input, message);
        return message;
      }

      function handleSubmit(event) {
        event.preventDefault();

        const form = event.currentTarget;
        const status = document.getElementById("form-status");
        const inputs = Array.from(form.querySelectorAll("input"));
        const firstInvalidInput = inputs.find((input) => updateField(input));

        if (firstInvalidInput) {
          status.textContent = "Please correct the highlighted fields before submitting.";
          firstInvalidInput.focus();
          return;
        }

        status.textContent = "Thanks. Your support request is ready to send.";
        form.reset();
        inputs.forEach((input) => {
          formState.values[input.name] = "";
          formState.errors[input.name] = "";
          setFieldError(input, "");
        });
      }

      function bindFormEvents() {
        const form = document.getElementById("support-form");
        const status = document.getElementById("form-status");

        form.addEventListener("submit", handleSubmit);
        form.querySelectorAll("input").forEach((input) => {
          input.addEventListener("blur", () => updateField(input));
          input.addEventListener("input", () => {
            status.textContent = "";
            if (formState.errors[input.name]) {
              updateField(input);
            }
          });
        });
      }

      document.getElementById("app").innerHTML = ContactForm();
      bindFormEvents();
    </script>
  </body>
</html>
